using System;

// PROGRAM: Eksplorasi Format Biner dan Heksadesimal di C#
byte value = 0b1010_1100; // 0xAC dalam heksadesimal, atau 172 desimal

Console.WriteLine($"Format Desimal: {value}");
Console.WriteLine($"Format Heksadesimal: 0x{value:X2}");
Console.WriteLine($"Format Biner: {Convert.ToString(value, 2).PadLeft(8, '0')}");

// Operasi Bitwise: AND, OR, XOR
byte mask = 0b0000_1111; // Mengisolasi 4 bit bawah (lower nibble)
byte lowerNibble = (byte)(value & mask);

Console.WriteLine($"Lower Nibble (Biner): {Convert.ToString(lowerNibble, 2).PadLeft(8, '0')}");
Console.WriteLine($"Lower Nibble (Desimal): {lowerNibble}");

