using System;

public class HexConverter
{
    public static int HexToDecimal(string hex)
    {
        if (string.IsNullOrWhiteSpace(hex)) return 0;
        int result = 0;
        foreach (char c in hex.Trim().ToUpperInvariant())
        {
            int val;
            if (c >= '0' && c <= '9') val = c - '0';
            else if (c >= 'A' && c <= 'F') val = 10 + (c - 'A');
            else continue;

            result = (result << 4) | val;
        }
        return result;
    }

    public static void Main()
    {
        Console.WriteLine($"FF -> {HexToDecimal("FF")}");
        Console.WriteLine($"2A -> {HexToDecimal("2A")}");
    }
}
